class GridBatcher(Batcher):
    """ALN2 anchor rows (8 per segment, one random phase per segment) with the phase drawn on the dense grid."""

    def __init__(self, coh, spec, row, dev, grid):
        super().__init__(coh, spec, row, dev); self.grid = int(grid)

    def rows(self, batch, rng, anchors=8, pairing="train", roll=False):
        g = self.grid
        step = max(g, (self.seg_len // anchors) // g * g)  # anchor spacing on the grid (probe 1033623 caught 80 % 3 != 0)
        phase = g * rng.integers(0, max(1, step // g), size=len(batch))
        t = (phase[:, None] + np.arange(anchors)[None] * step).reshape(-1)
        b = np.repeat(np.arange(len(batch)), anchors)
        bi = np.asarray(batch)
        e0 = np.array([self.coh_segments[i]["e0"] for i in batch])[b] + t
        s0s, ks = (self.s0_train, self.key_train) if pairing == "train" else (self.s0_true, self.key_true)
        src = np.roll(np.arange(len(batch)), 1) if roll else np.arange(len(batch))
        s0 = s0s[bi][src][b] + t
        keys = torch.tensor(ks[bi][src][b] * 1000 + t, device=self.dev)
        out = [torch.tensor(e0, device=self.dev), torch.tensor(s0, device=self.dev), keys]
        if self.selection:
            out.append(torch.tensor(self.s0_ign[bi][b] + t, device=self.dev))
            out.append(torch.tensor(b, device=self.dev))
        return out


class EpochEncoder(nn.Module):
    """list([x [B, C, T]]) -> [B, d] (one backbone patch per padded epoch); repaired channel-aware readout (amendment A1)."""

    def __init__(self, backbone, d=32):
        super().__init__(); self.bb = backbone; self.head = make_head(backbone, d)

    def forward(self, patches):
        return self.head(self.bb(patches[0]))[:, 0]


